            // TODO API_TEST_START
            java.io.File sourceFile = new java.io.File(grid_png);
            java.io.File tempSource = new java.io.File(output_dir, "temp_source_createThumbnails.png");
            java.nio.file.Files.copy(sourceFile.toPath(), tempSource.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING);

            java.util.List<java.io.File> files = java.util.Collections.singletonList(tempSource);
            net.coobird.thumbnailator.Thumbnailator.createThumbnails(
                files,
                net.coobird.thumbnailator.name.Rename.PREFIX_DOT_THUMBNAIL,
                50,
                50
            );

            java.io.File expectedOutputFile = new java.io.File(output_dir, "thumbnail.temp_source_createThumbnails.png");
